import type { Tafel } from "./plural";

/**
 * Die schwedische Tafel (WI-0211) - die neunte Sprache. Aufbau und Kommentare sind die der deutschen
 * Quelle: Wer einen Schlüssel sucht, findet ihn an derselben Stelle, und ein `diff` gegen `de.ts`
 * zeigt nur Text.
 *
 * 🔴 **Für DSA gibt es keine schwedische Ausgabe.** Die Begriffe sind hier gesetzt, in schlichtem
 * Schwedisch, und gelten von nun an; die Liste steht im Work Item WI-0211 §2.2. Spätere Sitzungen
 * übernehmen sie, statt neu zu wählen.
 *
 * 🔴 **Namen werden nicht übersetzt:** Orte, Wege, Kartenserien, die Monate (Praios … Rahja), die
 * Währungen (`Dukat`, `Silbertaler`, `Heller`), die Werktitel und `Schritt` in der Maßstabsleiste.
 * „Aventurien“ heißt auf Schwedisch **Aventurien**, wie im Deutschen.
 *
 * 🪤 **Aufschriften stehen im Imperativ** („Spara“, „Avbryt“, „Stäng“) - im Schwedischen die übliche
 * Form einer Aufschrift und die einzige ohne Anrede.
 */
