    "transportInfo.button": "Förklara transportmedel",
    "transportInfo.button.title": "Hur snabbt varje transportmedel är: på varje vägtyp, i berget och i luften",
    "transportInfo.intro":
        "Hur snabbt en resa går framåt beror på transportmedlet *och* på vägtypen. Ett sällskap till fots klarar på riksvägen {road} mil i timmen, på ett bergspass bara {pass}. Tabellerna anger mil om dagen och farten i mil per timme (1 mil = 1 000 Schritt, ungefär 1 km).",
    "transportInfo.landTravel": "Landresa",
    "transportInfo.riverTravel": "Flodresa",
