    "planner.route.shortest.title": "Tar fram den kortaste resrutten",
    "planner.minimizeTransfers": "Minimera byten",
    "planner.hurry": "Ilmarsch",
    // Die Pille an einer Etappe, in die eine Rast fällt (WI-0087 P8): EIN Wort - sie sagt DASS, nicht wie viel.
    // Die Stundenzahl steht im Infopanel (`infoPanel.stage.figure.rest`), die Zeile ist eng.
    "planner.rest": "Vila",
    "planner.hurry.partial": "Ilmarsch delvis",
    "planner.hurry.title":
        "Där det går reses det i ilmarsch. Olämpliga avsnitt behåller normal fart; den högre belastningen kan kräva extra återhämtning, som planen inte räknar med.",
    // 🔴 Der Deckel nennt nur das Ergebnis, die Rechnung steht im Inneren (Betreiber 2026-10-05). Die Zahl wird
    // hervorgehoben, das Wort nicht - das besorgt `AvmText`, hier wird nichts von Hand eingefärbt.
    "planner.hurry.lid": "{saved} tidsvinst i ilmarsch",
    "planner.hurry.lid.tiny": "Några minuters tidsvinst i ilmarsch",
    "planner.hurry.impossible": "Ilmarsch inte möjlig",
    "planner.hurry.lid.none": "Inget avsnitt av resan går i ilmarsch",
    // 🔴 Die Rechnung steht als TABELLE (WI-0087 P11, Betreiber 2026-10-06: „vielleicht kannst du die rechnung in
    // eine tabelle tun"): links die Benennung, rechts der Wert. Deshalb sind Benennung und Wert zwei Schlüssel; die
    // Zahlen, Einheiten und Rundungen sind unverändert, nur der Doppelpunkt ist mit der Tabelle entfallen.
    "planner.hurry.stretch.label": "Lämpligt",
    "planner.hurry.stretch": "{miles} av {total}",
    "planner.hurry.days.label": "Rest i ilmarsch",
    "planner.hurry.days": "{hurried} av {total} resdagar",
    "planner.hurry.factor.label": "Faktor en ildag",
    "planner.hurry.factor.value": "{n} gånger",
    "planner.hurry.saved.label": "Därav vinsten",
    // 🔴 Die Regel der Geographia, aufgelockert in drei Sätze und eine Aufzählung - **Wort für Wort dieselbe**
    // (WI-0087 P11). Was früher ein Absatz war, steht jetzt als Tempo, als Aufzählung „gilt / gilt nicht“ und als
    // Nachsatz; gestrichen ist nichts.
    "planner.hurry.rule.pace":
        "I ilmarsch går resande och dragdjur en och en halv gång, forvagnar och vagnar 1,25 gånger sin dagsprestation - och det bara varannan resdag, mer går inte att hålla i längden.",
    "planner.hurry.rule.whereYes": "Det gäller på riksvägar, landsvägar och vägar, till fots även på stigar;",
    "planner.hurry.rule.whereNo":
        "inte över bergspass, inte på tvären, inte genom träsk eller regnskog och inte på uppblött underlag, djupsnö eller is.",
    "planner.hurry.rule.sleds": "En släde ilar på snö och is. Flod- och sjöfart och flygning känner ingen ilmarsch.",
    "planner.hurry.none": "På den här resan är inget avsnitt lämpligt för ilmarsch; den räknar i normal fart.",
    "planner.hurry.strain":
        "Planen räknar bara tiden. Ökad utmattning, skaderisken och belastningen på rid- och dragdjur står inte i den.",
    "planner.minimizeTransfers.title": "Tar fram resrutten med minst antal byten mellan transportmedlen",
    "planner.travelHoursLabel": "Restimmar per dag:",
    "planner.travelHours.title":
        "Restimmar per dag på land och i luften; resten av dagen är vila. Det vilas först när timmarna är förbrukade och det ännu ligger väg framför sällskapet. Ombord gäller besättningens dag (ⓘ Transportmedel). 24 betyder: utan vila, också ombord.",
    "planner.options.summary.hoursPerDay": "{n} h/dag",
    "planner.travelStartLabel": "Resstart:",
    "planner.travelStart.title":
        "Dag och aventurisk månad för avfärden. Kalendern löper med, och årstiden förlänger varje etapp vars underlag den blöter upp eller fryser. Rutten undviker vägar som är avstängda vid ankomsten, under „Snabbaste“ i snö även de långsamma. Släden går bara med resstart. Utan månad räknar planeraren utan datum och årstid.",
    "planner.travelStart.none": "Obestämd (inga årstider)",
    "planner.travelStart.noneShort": "Obestämd",
    "planner.lodgingLabel": "Inkvartering:",
    "planner.lodging.title":
        "Hur sällskapet övernattar där ett värdshus går att nå. Det avgör vägtypen vid resdagens slut: Riksväg, landsväg och väg leder till värdshuset, på stig, pass, ökenstig och på tvären sovs det gratis under bar himmel, på flod och hav ombord. Valet bestämmer också hur tullmannen bedömer de resande.",
