    "inhalte.info.text":
        "Det här fönstret sköter innehåll som inte är kartobjekt. En källa är en gemensam katalogpost; dess användningar tillhör de enskilda objekten. Ett litteraturverk bär sina ordnade start- och spelplatser. En förekomst (fauna, flora, varor, arter) bär sina platser med förhandsvisning av träffar och sina regler skrivskyddade. Det som kommer från Legacy eller wikin förblir markerat som sådant; ett ändrat värde är skyddat före nästa synkronisering. Ett korpus är erbjudandet bakom källorna på en domän; vid ett belägg gäller dess uppgifter för alla källor på domänen.",
