    // „Regeln als Text“ im Reiter Vorkommen (WI-0254 §13): die Ansicht mit Textfeld und Vorschau, die Kurzreferenz der Schreibweise und die Sätze zum Übernehmen. Die Schreibweise selbst (Schlüsselwörter, Zeichen, Namen der Landschaftsarten) bleibt deutsch.
