    "inhalte.vorkommen.text.hinweisFeld":
        "Ctrl + Enter kontrollerar. Ett svar i förhandsgranskningen skriver om texten och kontrollerar igen; inget skapas förrän ”Ta över”.",
    "inhalte.vorkommen.text.schreibweise": "Skrivsätt",
    "inhalte.vorkommen.text.ungeprueft":
        "Ännu inte kontrollerad. ”Kontrollera” läser texten och visar vad som blir av den; inget skapas förrän ”Ta över”.",
