    "inhalte.vorkommen.text.antwortGesperrt":
        "Möjligt först efter en ny kontroll: Texten har ändrats sedan den förra, eller en begäran pågår.",
    "inhalte.vorkommen.text.fehler.allgemein": "Servern godtog inte begäran.",
    "inhalte.vorkommen.text.fehler.stelle":
        "Platsen i texten passar inte längre till svaret; ”Kontrollera” visar det aktuella läget.",
    "inhalte.vorkommen.text.alsText": "Som text",
    "inhalte.vorkommen.text.alsTextTitel": "Visa inläggets sparade regler i skrivsättet från ”Regler som text”",
