    "inhalte.vorkommen.text.woerter.arten": "Landskapstyper · {ebene}",
    "inhalte.vorkommen.text.woerter.richtungen": "Riktningar",
    "inhalte.vorkommen.text.woerter.beziehungen": "Relationer",
    "inhalte.vorkommen.text.woerter.kategorien": "Kategorier",
    "inhalte.vorkommen.text.ref.aufbau": "Textens uppbyggnad",
    "inhalte.vorkommen.text.ref.quelle.name": "Källa",
    "inhalte.vorkommen.text.ref.quelle.text":
        "gäller för alla följande inlägg till nästa Quelle-rad; ”Quelle: –” avslutar den. Sidorna står efter ”, S.”.",
    "inhalte.vorkommen.text.ref.kopf.name": "Rubrik",
    "inhalte.vorkommen.text.ref.kopf.text":
        "Namn i radens början; kategori inom parentes. Inlägg med samma namn: ”(Flora, [[Wiki-Titel]])”. Finns inlägget inte: ”(Flora, neu)”.",
    "inhalte.vorkommen.text.ref.regel.name": "Regel",
    "inhalte.vorkommen.text.ref.regel.text":
        "En rad ”| Beziehung = Ausdruck” som en parameter i wikins infobox (Verbreitung, Herkunft, Regionen, Vorkommen); den får stå flera gånger. En indragen rad utan ”|” fortsätter uttrycket på raden ovanför.",
    "inhalte.vorkommen.text.ref.zeichen.name": "Tecken",
    "inhalte.vorkommen.text.ref.zeichen.neueRegel": "ny regel",
    "inhalte.vorkommen.text.ref.zeichen.oder": "eller",
    "inhalte.vorkommen.text.ref.zeichen.und": "och",
    "inhalte.vorkommen.text.ref.zeichen.ohne": "utan",
    "inhalte.vorkommen.text.ref.zeichen.gilt": "Tecken räknas bara utanför ”[[…]]” och ”(…)”.",
    "inhalte.vorkommen.text.ref.glied.name": "Led",
    "inhalte.vorkommen.text.ref.glied.text":
        "Mellan tecknen står ett led, och ett led är ett villkor i regelredigeraren. Dess delar står i valfri ordning, var och en högst en gång:",
    "inhalte.vorkommen.text.ref.arten.name": "Landskapstyper",
    "inhalte.vorkommen.text.ref.arten.oder": "(sinsemellan ELLER)",
    "inhalte.vorkommen.text.ref.flaeche.name": "Område",
    "inhalte.vorkommen.text.ref.flaeche.ohneIn":
        "utan ”in” om namnet inte är en landskapstyp (områdena ”Meer” och ”See” kräver ”in”)",
    "inhalte.vorkommen.text.ref.flaeche.mehrdeutig": "vid tvetydigt namn",
    "inhalte.vorkommen.text.ref.flaeche.wartet": "(området finns ännu inte)",
    "inhalte.vorkommen.text.ref.klima.name": "Klimat",
    "inhalte.vorkommen.text.ref.lage.name": "Läge",
    "inhalte.vorkommen.text.ref.lage.zwischen": "(mellan orterna ”–”, ”-” eller ”bis”)",
    "inhalte.vorkommen.text.ref.namen":
        "Namn står alltid i ”[[…]]” (landskapstyper, områden, orter, källor); därför får de innehålla komma, kolon, bindestreck och ”und”. ”[[Ziel|Anzeige]]” och påhängda bokstäver (”[[Steppe]]n”) är tillåtna; målet räknas. Ett område hittas först via sin wikititel, sedan via sitt namn; är det tvetydigt frågar förhandsgranskningen och skriver ”[[#Kennung|Name]]”. Tillägg inom parentes finns bara som ”(wartet)”. Stora och små bokstäver, ß/ss och accenter räknas inte vid jämförelsen så länge resultatet förblir entydigt. Det finns en övre gräns per regel och per inlägg; fyndet nämner den. Ett klick på ett ord infogar det vid markören.",
    "inhalte.vorkommen.text.ref.unterschied.kopf": "En skillnad mot wikin:",
    "inhalte.vorkommen.text.ref.unterschied.text":
        "Strikt från vänster till höger, utan företräde: ”[[A]], [[B]]: [[C]]” betyder ”(A eller B) och C”, och ”[[A]] außer [[X]], [[B]]” betyder ”(A utan X) eller B”. Wikin läser ”A, B: C” annorlunda, nämligen som ”A, eller C i B”: Där är bara det sista ledet före kolonet ramen. Där ramen står först (”[[Aventurien]]: [[Meridiana]], [[Orkland]]”), läser båda lika.",
    "inhalte.vorkommen.text.n.eintraege.one": "{n} inlägg",
    "inhalte.vorkommen.text.n.eintraege.other": "{n} inlägg",
    "inhalte.vorkommen.text.n.eintraegeAn.one": "{n} inlägg",
    "inhalte.vorkommen.text.n.eintraegeAn.other": "{n} inlägg",
    "inhalte.vorkommen.text.n.regeln.one": "{n} regel",
    "inhalte.vorkommen.text.n.regeln.other": "{n} regler",
    "inhalte.vorkommen.text.n.rueckfragen.one": "{n} fråga",
    "inhalte.vorkommen.text.n.rueckfragen.other": "{n} frågor",
    "inhalte.vorkommen.text.n.fehler.one": "{n} fel",
    "inhalte.vorkommen.text.n.fehler.other": "{n} fel",
