    // --- Neuigkeiten (WI-0139) ---
    "news.title": "Nyheter",
    "news.intro":
        "Vad som har hänt på Avesmaps sedan kartan kom ut i april 2026 — de större stegen, det finstilta utelämnar vi.",
    "news.foot": "Avesmaps är ett fanprojekt och byggs vidare löpande. Idéer och fel tas gärna emot på vår Discord.",
