    "corner.notes": "Upplysningar",
    "notes.title": "Upplysningar",
    "notes.keyboard": "Tangentbord",
    "notes.or": "eller",
    "notes.shortcutsOff":
        "Stäng av kortkommandon med enstaka bokstäver, siffror och tecken. Piltangenterna fungerar vidare. Hjälper när kartan styrs med rösten.",
    "notes.ringText":
        "Höger musknapp flyttar aldrig kartan. På datorn zoomar styrringen uppe till höger (+, −), vrider med pilarna till vänster och höger till närmaste väderstreck och riktar mot norr i mitten; pillret ”2D | 3D” ovanför lutar kartan och gör den platt igen. På telefonen gör två fingrar det; är kartan vriden står där en kompass, och ett tryck på den ställer norr uppåt. Den runda knappen med kartbrickan lutar kartan i 3D och gör den platt igen.",
    "notes.ringOnTouch": "Visa styrringen även på telefonen. Då går kartan att vrida och zooma utan två fingrar.",
    // „Karten auf Avesmaps“ fasst seit 2026-10-12 zusammen, was vorher „Kartenmaterial“ und „Kartenserien“ getrennt sagten.
    "notes.derivationUndocumented":
        "Hur den här versionen har uppstått ur originalkartan är uttryckligen inte dokumenterat. Serien används lokalt; om en offentlig leverans beslutas separat.",
    // Der Aufbau nach Legacys #legal-dialog (WI-0045 Stufe B, Betreiber 2026-09-27): Wappenbild, zwei
    // Aktionskacheln, klappbare Abschnitte mit Hinweiszeile. Die Rechtstexte selbst stehen in config/legal.
    "notes.badge": "Icke-kommersiellt fanprojekt",
    "notes.badge.alt": "DSA-fanprojektlogotyp",
    "notes.social.lead": "Var med och följ oss",
    "notes.social.body":
        "Frågor, återkoppling eller bara lust att vara med? Avesmaps-gemenskapen möts på Discord. På våra kanaler visar vi vad som är på gång.",
    "notes.social.action": "Till gemenskapen",
    "notes.kontakt.action": "Skriv ett meddelande",
    "notes.social.channel": "Avesmaps på {channel}",
    "notes.news.lead": "Vad är nytt?",
    "notes.news.body": "Avesmaps växer hela tiden — de viktigaste stegen sedan starten.",
    "notes.news.action": "Öppna nyheter",
    // Die Vorspannmarken der Absätze: Beschriftung, nicht Rechtstext (der steht in config/legal).
